from itertools import product

n = 17
def corr(s, k):
    return sum(s[i]*s[i+k] for i in range(n-k))

# check if maybe just the constraint c[7]=3 is impossible given the fixed values
count=0
for bits in product([-1,1], repeat=n):
    if bits[1]!=-1 or bits[6]!=1 or bits[9]!=-1:
        continue
    s=list(bits)
    if corr(s,7)==3 and corr(s,8)==-2 and corr(s,12)==0:
        count+=1
        if count<5:
            print(s, [corr(s,k) for k in range(1,17)])
print("total:", count)
